switch_kimi_code() {
  local theme_dir="${XDG_CONFIG_HOME:-$HOME/.config}/kimi-code-desktop"
  local theme_file="$theme_dir/amane.css"
  local scheme="dark"
  [ "${C[light]}" = "true" ] && scheme="light"
  mkdir -p "$theme_dir"

  local theme_tmp
  theme_tmp="$(mktemp "${theme_file}.XXXXXX")" || return 1
  cat > "$theme_tmp" << EOF
/* Auto-generated by switch-theme.sh */
:root, html[data-color-scheme=light], html[data-color-scheme=dark], html[data-color-scheme=system],
.markstream-vue, .dark .markstream-vue, .markstream-vue.dark {
  color-scheme: $scheme !important;
  --color-bg: ${C[base]} !important;
  --color-surface: ${C[mantle]} !important;
  --color-surface-raised: ${C[surface0]} !important;
  --color-surface-overlay: ${C[surface1]} !important;
  --color-surface-sunken: ${C[crust]} !important;
  --color-surface-deep: ${C[crust]} !important;
  --color-inline-code-bg: ${C[surface0]} !important;
  --color-well: ${C[mantle]} !important;
  --color-text: ${C[text]} !important;
  --color-text-strong: ${C[subtext1]} !important;
  --color-text-muted: ${C[subtext0]} !important;
  --color-text-faint: ${C[overlay1]} !important;
  --color-text-quaternary: ${C[overlay0]} !important;
  --color-text-on-accent: ${C[base]} !important;
  --color-line: ${C[surface1]} !important;
  --color-subtle: ${C[surface0]} !important;
  --color-line-strong: ${C[surface2]} !important;
  --color-selected: ${C[surface0]} !important;
  --color-selected-hover: ${C[surface1]} !important;
  --panel-tab-selected-bg: ${C[surface1]} !important;
  --color-hover: ${C[surface0]} !important;
  --color-sidebar-bg: ${C[crust]} !important;
  --color-sidebar-tint: ${C[mantle]} !important;
  --color-user-bubble-bg: ${C[surface0]} !important;
  --color-accent: ${C[accent]} !important;
  --color-accent-hover: ${C[mauve]} !important;
  --color-accent-soft: color-mix(in srgb, ${C[accent]} 16%, ${C[base]}) !important;
  --color-accent-bd: ${C[accent]} !important;
  --p-selection: color-mix(in srgb, ${C[accent]} 30%, transparent) !important;
  --color-code-selection: color-mix(in srgb, ${C[accent]} 35%, transparent) !important;
  --color-success: ${C[green]} !important;
  --color-success-soft: color-mix(in srgb, ${C[green]} 16%, ${C[base]}) !important;
  --color-success-bd: ${C[green]} !important;
  --color-warning: ${C[yellow]} !important;
  --color-warning-soft: color-mix(in srgb, ${C[yellow]} 16%, ${C[base]}) !important;
  --color-warning-bd: ${C[yellow]} !important;
  --color-orange: ${C[peach]} !important;
  --color-orange-soft: color-mix(in srgb, ${C[peach]} 16%, ${C[base]}) !important;
  --color-danger: ${C[red]} !important;
  --color-danger-soft: color-mix(in srgb, ${C[red]} 16%, ${C[base]}) !important;
  --color-danger-bd: ${C[red]} !important;
  --color-diff-add-bg: color-mix(in srgb, ${C[green]} 18%, ${C[base]}) !important;
  --color-diff-del-bg: color-mix(in srgb, ${C[red]} 18%, ${C[base]}) !important;
  --color-diff-add-fg: ${C[green]} !important;
  --color-diff-del-fg: ${C[red]} !important;
  --color-fill-1: ${C[surface0]} !important;
  --color-fill-2: ${C[surface1]} !important;
  --color-fill-4: ${C[overlay0]} !important;
  --color-bg-translucent: color-mix(in srgb, ${C[base]} 85%, transparent) !important;
  --color-attention: ${C[peach]} !important;
  --color-done: ${C[mauve]} !important;
  --color-done-soft: color-mix(in srgb, ${C[mauve]} 16%, ${C[base]}) !important;
  --color-done-bd: ${C[mauve]} !important;
  --color-info: ${C[blue]} !important;
  --color-term-magenta: ${C[mauve]} !important;
  --color-term-cyan: ${C[teal]} !important;
  --color-term-black: ${C[surface2]} !important;
  --color-composer-bg: ${C[mantle]} !important;
  --color-composer-line: ${C[surface1]} !important;
  --color-composer-focus-line: ${C[accent]} !important;
  --color-send-bg: ${C[accent]} !important;
  --color-send-bg-hover: ${C[mauve]} !important;
  --color-send-icon: ${C[base]} !important;
  --color-send-bg-disabled: ${C[surface0]} !important;
  --color-send-icon-disabled: ${C[overlay1]} !important;
  --color-menu-bg: ${C[surface0]} !important;
  --panel: ${C[mantle]} !important;
  --panel2: ${C[crust]} !important;
  --bg: ${C[base]} !important;
  --canvas: ${C[base]} !important;
  --blue: ${C[accent]} !important;
  --blue2: ${C[mauve]} !important;
  --soft: color-mix(in srgb, ${C[accent]} 16%, ${C[base]}) !important;
  --bd: ${C[accent]} !important;
  --logo: ${C[accent]} !important;
  --bluebg: ${C[surface0]} !important;
  --blueln: ${C[surface1]} !important;
  --ok: ${C[green]} !important;
  --warn: ${C[yellow]} !important;
  --star: ${C[yellow]} !important;
  --err: ${C[red]} !important;
  --markdown-text-color: ${C[text]} !important;
  --markdown-secondary-icon-color: ${C[subtext0]} !important;
  --markdown-link-color: ${C[blue]} !important;
  --markdown-border-color: ${C[surface1]} !important;
  --markdown-quote-rule-color: ${C[surface2]} !important;
  --markdown-code-background: ${C[mantle]} !important;
  --markdown-code-header-background: ${C[surface0]} !important;
  --markdown-code-action-background: ${C[surface0]} !important;
  --markdown-code-action-hover-background: ${C[surface1]} !important;
  --markdown-code-toggle-background: ${C[surface0]} !important;
  --markdown-code-toggle-selected-background: ${C[surface1]} !important;
  --markdown-image-background: ${C[mantle]} !important;
  --markdown-syntax-heading-color: ${C[blue]} !important;
  --markdown-syntax-property-color: ${C[blue]} !important;
  --markdown-syntax-string-color: ${C[green]} !important;
  --markdown-syntax-keyword-color: ${C[mauve]} !important;
  --markdown-syntax-function-color: ${C[blue]} !important;
  --markdown-syntax-number-color: ${C[peach]} !important;
  --markdown-syntax-comment-color: ${C[overlay1]} !important;
  --markdown-code-gutter-background: ${C[mantle]} !important;
  --markdown-code-scrollbar-thumb: ${C[surface2]} !important;
  --markdown-code-scrollbar-thumb-hover: ${C[overlay1]} !important;
  --markdown-diagram-actor-background: ${C[surface0]} !important;
  --markdown-diagram-actor-border-color: ${C[yellow]} !important;
  --markdown-diagram-actor-text-color: ${C[text]} !important;
  --tooltip-bg: ${C[surface0]} !important;
  --tooltip-fg: ${C[text]} !important;
  --code-bg: ${C[mantle]} !important;
  --code-header-bg: ${C[surface0]} !important;
  --markstream-diff-editor-bg: ${C[mantle]} !important;
  --markstream-diff-editor-fg: ${C[text]} !important;
  --markstream-diff-unchanged-fg: ${C[text]} !important;
  --markstream-diff-unchanged-bg: ${C[mantle]} !important;
  --markstream-diff-panel-bg: ${C[mantle]} !important;
  --markstream-diff-panel-bg-soft: ${C[mantle]} !important;
  --markstream-diff-panel-bg-strong: ${C[surface0]} !important;
  --ms-background: from ${C[base]} h s l !important;
  --ms-foreground: from ${C[text]} h s l !important;
  --ms-muted: from ${C[mantle]} h s l !important;
  --ms-muted-foreground: from ${C[subtext0]} h s l !important;
  --ms-secondary: from ${C[surface0]} h s l !important;
  --ms-secondary-foreground: from ${C[text]} h s l !important;
  --ms-accent: from ${C[surface1]} h s l !important;
  --ms-accent-foreground: from ${C[text]} h s l !important;
  --ms-primary: from ${C[accent]} h s l !important;
  --ms-primary-foreground: from ${C[base]} h s l !important;
  --ms-destructive: from ${C[red]} h s l !important;
  --ms-destructive-foreground: from ${C[base]} h s l !important;
  --ms-border: from ${C[surface1]} h s l !important;
  --ms-ring: from ${C[accent]} h s l !important;
  --ms-popover: from ${C[mantle]} h s l !important;
  --ms-popover-foreground: from ${C[text]} h s l !important;
  --ms-info: from ${C[blue]} h s l !important;
  --ms-info-foreground: from ${C[base]} h s l !important;
  --ms-success: from ${C[green]} h s l !important;
  --ms-success-foreground: from ${C[base]} h s l !important;
  --ms-warning: from ${C[yellow]} h s l !important;
  --ms-warning-foreground: from ${C[base]} h s l !important;
  --ms-diff-added: from ${C[green]} h s l !important;
  --ms-diff-removed: from ${C[red]} h s l !important;
  --ms-highlight: from ${C[yellow]} h s l !important;
  --ms-highlight-foreground: from ${C[base]} h s l !important;
}
body { background: ${C[base]} !important; color: ${C[text]} !important; }
EOF
  mv "$theme_tmp" "$theme_file"
}
